// Windows-only tests for the private kernel trace session (src/win/etw.cpp). They need an elevated
// administrator (the GitHub Windows runner is one). The session is started for real, a disk
// workload is generated by this process, and the attribution / cleanup is asserted. Measurements
// (top drivers, cost, counters) are printed for the CI log.
#include <windows.h>

#include <chrono>
#include <cstdio>
#include <string>
#include <vector>

#include "etw.hpp"
#include "kernel_stats.hpp"
#include "telemetry.hpp"
#include "test_framework.hpp"

using opensweep::kstats::DiskProcessView;
using opensweep::win::kEtwSessionName;
using opensweep::win::KernelSession;

namespace {

unsigned logical_processors() {
    SYSTEM_INFO si{};
    GetSystemInfo(&si);
    return si.dwNumberOfProcessors > 0 ? si.dwNumberOfProcessors : 1;
}

std::wstring temp_path() {
    wchar_t dir[MAX_PATH];
    const DWORD n = GetTempPathW(MAX_PATH, dir);
    if (n == 0 || n >= MAX_PATH) return L"opensweep-etw-test.bin";
    wchar_t name[MAX_PATH];
    if (!GetTempFileNameW(dir, L"osw", 0, name)) return std::wstring(dir) + L"opensweep-etw-test.bin";
    return name;
}

// Writes, flushes and reads back `mib` MiB with FILE_FLAG_NO_BUFFERING | WRITE_THROUGH, so the disk
// I/O is issued by this thread (not by the cache manager's lazy writer).
bool disk_workload(int mib) {
    const std::wstring path = temp_path();
    HANDLE h = CreateFileW(path.c_str(), GENERIC_READ | GENERIC_WRITE, 0, nullptr, CREATE_ALWAYS,
                           FILE_ATTRIBUTE_NORMAL | FILE_FLAG_NO_BUFFERING | FILE_FLAG_WRITE_THROUGH |
                               FILE_FLAG_DELETE_ON_CLOSE,
                           nullptr);
    if (h == INVALID_HANDLE_VALUE) {
        std::fprintf(stderr, "  CreateFile failed: %lu\n", GetLastError());
        return false;
    }
    constexpr DWORD kChunk = 1u << 20;  // page-aligned buffer satisfies any sector size
    void* buf = VirtualAlloc(nullptr, kChunk, MEM_COMMIT | MEM_RESERVE, PAGE_READWRITE);
    bool ok = buf != nullptr;
    if (ok) {
        auto* p = static_cast<unsigned char*>(buf);
        for (DWORD i = 0; i < kChunk; ++i) p[i] = static_cast<unsigned char>(i * 31u + 7u);
        for (int i = 0; ok && i < mib; ++i) {
            DWORD done = 0;
            ok = WriteFile(h, buf, kChunk, &done, nullptr) && done == kChunk;
        }
        ok = ok && FlushFileBuffers(h);
        LARGE_INTEGER zero{};
        ok = ok && SetFilePointerEx(h, zero, nullptr, FILE_BEGIN);
        for (int i = 0; ok && i < mib; ++i) {
            DWORD done = 0;
            ok = ReadFile(h, buf, kChunk, &done, nullptr) && done == kChunk;
        }
        if (!ok) std::fprintf(stderr, "  disk workload failed: %lu\n", GetLastError());
        VirtualFree(buf, 0, MEM_RELEASE);
    }
    CloseHandle(h);
    return ok;
}

const DiskProcessView* find_pid(const std::vector<DiskProcessView>& v, std::uint32_t pid) {
    for (const auto& p : v)
        if (p.pid == pid) return &p;
    return nullptr;
}

}  // namespace

TEST(win_etw_kernel_session_sees_dpc_isr_and_attributes_disk_io) {
    KernelSession::Options o;
    o.logical_processors = logical_processors();
    KernelSession s(o);
    const bool started = s.start();
    auto st = s.status();
    std::printf("  start=%d running=%d level=%d reason=%s\n", started ? 1 : 0, st.running ? 1 : 0, st.level,
                st.reason.c_str());
    CHECK(started);
    CHECK(st.running);
    CHECK(KernelSession::session_exists(kEtwSessionName));
    if (!started) return;

    opensweep::telemetry::Sample s0;
    s.fill_sample(s0);  // starts the per-sample interval
    Sleep(1500);        // rundown (process / thread / image DCStart) arrives first
    CHECK(disk_workload(16));
    Sleep(3500);        // FlushTimer is 1 s; give the consumer time to drain

    opensweep::telemetry::Sample s1;
    s.fill_sample(s1);
    const auto lat = s.latency();
    const auto disk = s.disk_activity();
    const auto faults = s.hard_faults();
    const auto c = s.counters();
    st = s.status();

    std::printf("  events=%llu dpc/isr=%llu disk=%llu hardfaults=%llu malformed=%llu unknownRoutine=%llu "
                "unattributed=%llu kernelImages=%zu lost=%llu cost=%.3f%% of one CPU\n",
                static_cast<unsigned long long>(c.events), static_cast<unsigned long long>(c.dpc_isr),
                static_cast<unsigned long long>(c.disk), static_cast<unsigned long long>(c.hard_faults),
                static_cast<unsigned long long>(c.malformed), static_cast<unsigned long long>(c.unknown_routine),
                static_cast<unsigned long long>(c.unattributed), s.kernel_images(),
                static_cast<unsigned long long>(st.events_lost), st.cost_percent);
    std::printf("  system: dpc=%.4f%% isr=%.4f%% worstDpc=%.1f us worstIsr=%.1f us (covered %lld ms)\n",
                lat.dpc_percent, lat.isr_percent, lat.worst_dpc_us, lat.worst_isr_us,
                static_cast<long long>(lat.covered_ms));
    std::printf("  top drivers (by longest routine):\n");
    for (std::size_t i = 0; i < lat.drivers.size() && i < 10; ++i) {
        const auto& d = lat.drivers[i];
        const std::string desc = opensweep::kstats::driver_description(d.name);
        std::printf("    %-24s dpc=%llu isr=%llu total=%.0f us max=%.1f us hist=[%llu %llu %llu %llu %llu %llu %llu %llu]%s%s\n",
                    d.name.c_str(), static_cast<unsigned long long>(d.dpc_count),
                    static_cast<unsigned long long>(d.isr_count), d.total_us(), d.max_us,
                    static_cast<unsigned long long>(d.histogram[0]), static_cast<unsigned long long>(d.histogram[1]),
                    static_cast<unsigned long long>(d.histogram[2]), static_cast<unsigned long long>(d.histogram[3]),
                    static_cast<unsigned long long>(d.histogram[4]), static_cast<unsigned long long>(d.histogram[5]),
                    static_cast<unsigned long long>(d.histogram[6]), static_cast<unsigned long long>(d.histogram[7]),
                    desc.empty() ? "" : "  = ", desc.c_str());
    }
    std::printf("  disk (last 2 min):\n");
    for (std::size_t i = 0; i < disk.size() && i < 5; ++i)
        std::printf("    pid=%u %-24s read=%.0f B/s write=%.0f B/s ios=%llu mean=%.2f ms max=%.2f ms\n", disk[i].pid,
                    disk[i].name.c_str(), disk[i].read_bps, disk[i].write_bps,
                    static_cast<unsigned long long>(disk[i].ios), disk[i].mean_latency_ms, disk[i].max_latency_ms);
    std::printf("  hard faults (last 2 min):\n");
    for (std::size_t i = 0; i < faults.size() && i < 5; ++i)
        std::printf("    pid=%u %-24s %.2f/s\n", faults[i].pid, faults[i].name.c_str(), faults[i].faults_per_sec);

    // DPC / ISR events were seen and mapped to at least one named driver.
    CHECK(c.dpc_isr > 0);
    std::size_t named = 0;
    for (const auto& d : lat.drivers)
        if (d.name != "unknown") ++named;
    CHECK(named > 0);
    CHECK(s.kernel_images() > 0);
    // Disk bytes attributed to this process (issuing thread -> pid).
    const DiskProcessView* self = find_pid(disk, GetCurrentProcessId());
    CHECK(self != nullptr);
    if (self) {
        CHECK(self->ios > 0);
        CHECK(self->write_bps > 0.0);
        CHECK(self->read_bps > 0.0);
        std::printf("  own process: %s read=%.0f B/s write=%.0f B/s ios=%llu\n", self->name.c_str(), self->read_bps,
                    self->write_bps, static_cast<unsigned long long>(self->ios));
    }
    // Per-sample fields.
    CHECK(s1.kernel_valid);
    bool own_in_sample = false;
    for (const auto& p : s1.kernel_processes)
        if (p.pid == GetCurrentProcessId() && p.read_bps + p.write_bps > 0.0) own_in_sample = true;
    CHECK(own_in_sample);
    CHECK(c.malformed * 100 <= c.events + 100);  // decoding sanity: malformed events stay rare

    const auto t0 = std::chrono::steady_clock::now();
    s.stop();
    const auto stop_ms =
        std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - t0).count();
    std::printf("  stop took %lld ms\n", static_cast<long long>(stop_ms));
    CHECK(stop_ms < 8000);
    CHECK(!s.status().running);
    CHECK(!KernelSession::session_exists(kEtwSessionName));  // QueryTrace fails: no orphan session
}

TEST(win_etw_disable_enable_and_stale_cleanup) {
    KernelSession s;
    CHECK(s.start());
    CHECK(KernelSession::session_exists(kEtwSessionName));
    // setEtw false: session stopped, reason reported.
    auto st = s.set_enabled(false);
    CHECK(!st.running);
    CHECK(!st.enabled);
    CHECK(!st.reason.empty());
    CHECK(!KernelSession::session_exists(kEtwSessionName));
    // setEtw true: running again.
    st = s.set_enabled(true);
    CHECK(st.running);
    CHECK(KernelSession::session_exists(kEtwSessionName));
    s.stop();
    CHECK(!KernelSession::session_exists(kEtwSessionName));

    // Crash recovery: a session left behind under our name is stopped and replaced at start. The
    // "leftover" instance's supervisor sleeps long so it cannot react while `fresh` runs.
    {
        KernelSession::Options slow;
        slow.supervise_ms = 600'000;
        KernelSession leftover(slow);
        CHECK(leftover.start());
        KernelSession fresh;
        CHECK(fresh.start());
        CHECK(fresh.status().running);
        CHECK(KernelSession::session_exists(kEtwSessionName));
        fresh.stop();
        CHECK(!KernelSession::session_exists(kEtwSessionName));
        const auto t0 = std::chrono::steady_clock::now();
        leftover.stop();  // its session is already gone: must not hang
        const auto ms =
            std::chrono::duration_cast<std::chrono::milliseconds>(std::chrono::steady_clock::now() - t0).count();
        std::printf("  leftover stop took %lld ms\n", static_cast<long long>(ms));
        CHECK(ms < 8000);
    }
    CHECK(!KernelSession::session_exists(kEtwSessionName));

    // Someone else stops our session: the supervisor notices and reports why.
    {
        KernelSession a;
        CHECK(a.start());
        CHECK(KernelSession::stop_session(kEtwSessionName));
        Sleep(3000);
        const auto sa = a.status();
        std::printf("  after external stop: running=%d reason=%s\n", sa.running ? 1 : 0, sa.reason.c_str());
        CHECK(!sa.running);
        CHECK(!sa.reason.empty());
        a.stop();
    }
    CHECK(!KernelSession::session_exists(kEtwSessionName));
    // A stop of a session that does not exist is harmless.
    unsigned long err = 0;
    CHECK(!KernelSession::stop_session(kEtwSessionName, &err));
}
